\set ON_ERROR_STOP on
BEGIN;
INSERT INTO price_snapshots (price_snapshot_id, card_id, source, price, card_status, traded_at, collected_at, created_at, validation_status)
SELECT 'ko_bf0615_'||p.card_id, p.card_id, 'KO_ESTIMATED', p.price, p.card_status, TIMESTAMP '2026-06-15 23:45:00', TIMESTAMP '2026-06-15 23:45:00', now(), 'VALID'
FROM price_snapshots p JOIN cards c ON c.card_id=p.card_id
WHERE p.source='KO_ESTIMATED' AND p.traded_at>='2026-06-14' AND p.traded_at<'2026-06-15'
  AND c.rarity_code NOT IN ('A','K','S')
  AND NOT EXISTS (SELECT 1 FROM price_snapshots x WHERE x.card_id=p.card_id AND x.source='KO_ESTIMATED' AND x.traded_at>='2026-06-15' AND x.traded_at<'2026-06-16');
